          ip: item.ip,
          count: item._count.ip,
        })),
        visits: filteredVisits,
      });
    } catch (error) {
      logger.error(
        { err: error, route: "/api/admin/analytics" },
        "Error fetching analytics"
      );
      return NextResponse.json(
        { error: "Failed to fetch analytics" },
        { status: 500 }
      );
    }
  }
);

